fixtures = 'lib/product/p5_information_architecture/p5_fixtures.dart'
replace_once(
    fixtures,
    """  static const List<P5VerificationFixture> verificationResults =\n""",
    """  static List<P5EvidenceFixture> evidenceForRun(String runId) {\n    if (!runs.any((run) => run.id == runId)) {\n      return const <P5EvidenceFixture>[];\n    }\n    return P5EvidenceKind.values\n        .map((kind) => _evidenceFixture(runId, kind))\n        .toList(growable: false);\n  }\n\n  static P5EvidenceFixture? evidenceById({\n    required String runId,\n    required String evidenceId,\n  }) {\n    for (final item in evidenceForRun(runId)) {\n      if (item.id == evidenceId) {\n        return item;\n      }\n    }\n    return null;\n  }\n\n  static P5EvidenceFixture _evidenceFixture(\n    String runId,\n    P5EvidenceKind kind,\n  ) {\n    final content = switch (kind) {\n      P5EvidenceKind.textMetadata =>\n        'charset=utf-8\\nlines=42\\nsource=fixture://evidence/$runId/notes.txt',\n      P5EvidenceKind.binaryMetadata =>\n        'bytes=4096\\nmedia=application/octet-stream\\nsha256=NOT_COMPUTED_FIXTURE',\n      P5EvidenceKind.image =>\n        'dimensions=640x360\\nalt=Deterministic saved-run image preview\\nsource=fixture://evidence/$runId/preview.png',\n      P5EvidenceKind.markdown =>\n        '# Saved run summary\\n\\n- Run: $runId\\n- State: deterministic fixture\\n- Production evidence: not claimed',\n      P5EvidenceKind.json =>\n        '{\"runId\":\"$runId\",\"status\":\"fixture\",\"verified\":false}',\n      P5EvidenceKind.table =>\n        'name|state\\nplan|stored\\nverification|not_evaluated\\nrelease|unsupported',\n      P5EvidenceKind.diff =>\n        '--- before.txt\\n+++ after.txt\\n-old value\\n+new value',\n      P5EvidenceKind.citation =>\n        'title=Kristin deterministic citation\\nsource=fixture://citation/$runId\\nexcerpt=Saved-run citation fixture only.',\n      P5EvidenceKind.receipt =>\n        'receiptId=receipt.$runId\\noperation=fixture.evidence.open\\nresult=PASS_PRESENTATION_ONLY',\n    };\n    final mediaType = switch (kind) {\n      P5EvidenceKind.textMetadata => 'text/plain; charset=utf-8',\n      P5EvidenceKind.binaryMetadata => 'application/octet-stream',\n      P5EvidenceKind.image => 'image/png',\n      P5EvidenceKind.markdown => 'text/markdown',\n      P5EvidenceKind.json => 'application/json',\n      P5EvidenceKind.table => 'text/tabular',\n      P5EvidenceKind.diff => 'text/x-diff',\n      P5EvidenceKind.citation => 'application/vnd.kristin.citation',\n      P5EvidenceKind.receipt => 'application/vnd.kristin.receipt',\n    };\n    return P5EvidenceFixture(\n      id: 'evidence.$runId.${kind.name}',\n      runId: runId,\n      kind: kind,\n      title: '${kind.label} viewer fixture',\n      mediaType: mediaType,\n      byteLength: content.length,\n      summary:\n          '${kind.label} evidence saved with deterministic run fixture $runId.',\n      content: content,\n    );\n  }\n\n  static const List<P5VerificationFixture> verificationResults =\n""",
)

controller = 'lib/product/p5_information_architecture/p5_controller.dart'
replace_once(
    controller,
    """    _state = _state.copyWith(\n      selectedRunId: fixture.id,\n      selectedProjectId: fixture.projectId,\n      runState: fixture.state,\n""",
    """    _state = _state.copyWith(\n      selectedRunId: fixture.id,\n      selectedProjectId: fixture.projectId,\n      selectedEvidenceId: null,\n      runState: fixture.state,\n""",
)
replace_once(
    controller,
    """  void selectWorkspace(P5WorkspaceId workspace) {\n""",
    """  void selectEvidence(String? evidenceId) {\n    final runId = _state.selectedRunId;\n    final isSavedRun =\n        runId != null && P5PrototypeFixtures.runs.any((run) => run.id == runId);\n    if (!isSavedRun) {\n      _state = _state.copyWith(\n        selectedEvidenceId: null,\n        recoveryMessage:\n            'Typed evidence can only reopen from a deterministic saved run.',\n      );\n      notifyListeners();\n      return;\n    }\n    if (evidenceId == null) {\n      if (_state.selectedEvidenceId == null) {\n        return;\n      }\n      _state = _state.copyWith(selectedEvidenceId: null, recoveryMessage: null);\n      notifyListeners();\n      return;\n    }\n    final evidence = P5PrototypeFixtures.evidenceById(\n      runId: runId,\n      evidenceId: evidenceId,\n    );\n    if (evidence == null) {\n      _state = _state.copyWith(\n        recoveryMessage:\n            'Evidence "$evidenceId" is not part of saved run "$runId".',\n      );\n      notifyListeners();\n      return;\n    }\n    if (_state.selectedEvidenceId == evidence.id &&\n        _state.recoveryMessage == null) {\n      return;\n    }\n    _state = _state.copyWith(\n      selectedEvidenceId: evidence.id,\n      recoveryMessage: null,\n    );\n    notifyListeners();\n  }\n\n  void selectWorkspace(P5WorkspaceId workspace) {\n""",
)

verification = 'lib/product/p5_information_architecture/p5_verification_workspaces.dart'
replace_span(
    verification,
    '  Widget _evidenceWorkspace(BuildContext context) {\n',
    '  Widget _ownerModeWorkspace(BuildContext context) {\n',
    """  Widget _evidenceWorkspace(BuildContext context) {\n    final state = controller.state;\n    final advanced =\n        state.experienceLevel.index >= P5ExperienceLevel.advanced.index;\n    final savedRun = P5PrototypeFixtures.runs\n        .where((run) => run.id == state.selectedRunId)\n        .firstOrNull;\n    final evidence = savedRun == null\n        ? const <P5EvidenceFixture>[]\n        : P5PrototypeFixtures.evidenceForRun(savedRun.id);\n    final selected = savedRun == null\n        ? null\n        : evidence\n                .where((item) => item.id == state.selectedEvidenceId)\n                .firstOrNull ??\n            evidence.firstOrNull;\n    return _scrollWorkspace(\n      context,\n      children: <Widget>[\n        const _WorkspaceHeader(\n          title: 'Evidence',\n          subtitle:\n              'Reopen typed saved-run evidence without turning presentation fixtures into production claims.',\n          icon: Icons.receipt_long_outlined,\n        ),\n        for (final item in const <(String, String, String)>[\n          (\n            'evidence.plan-receipt',\n            'Plan receipt',\n            'Goals, bounded steps, and requested access',\n          ),\n          (\n            'evidence.run-timeline',\n            'Run timeline',\n            'Deterministic fixture events with retained context',\n          ),\n          (\n            'evidence.verification-summary',\n            'Verification summary',\n            'Test states separated from certification and support',\n          ),\n        ])\n          Card(\n            child: ListTile(\n              leading: const Icon(Icons.description_outlined),\n              title: Text(item.$2),\n              subtitle: Text(advanced ? '${item.$3}\\n${item.$1}' : item.$3),\n              trailing: const Icon(Icons.open_in_new),\n            ),\n          ),\n        const SizedBox(height: 12),\n        if (savedRun == null)\n          const _BoundaryNotice(\n            key: Key('evidence-no-saved-run'),\n            message:\n                'Select a saved run in Runs / Activity to reopen typed artifact, diff, citation, and receipt viewers. Current in-memory runs do not fabricate saved evidence.',\n          )\n        else ...<Widget>[\n          Card(\n            key: const Key('saved-run-evidence-index'),\n            child: Padding(\n              padding: const EdgeInsets.all(16),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: <Widget>[\n                  Text(\n                    'Saved evidence • ${savedRun.title}',\n                    style: Theme.of(context).textTheme.titleLarge,\n                  ),\n                  const SizedBox(height: 8),\n                  Text('${evidence.length} supported viewer types'),\n                  const SizedBox(height: 8),\n                  for (final item in evidence)\n                    ListTile(\n                      key: Key('evidence-item-${item.kind.name}'),\n                      selected: item.id == selected?.id,\n                      leading: Icon(_evidenceKindIcon(item.kind)),\n                      title: Text(item.kind.label),\n                      subtitle: Text(\n                        advanced\n                            ? '${item.summary}\\n${item.mediaType} • ${item.byteLength} bytes'\n                            : item.summary,\n                      ),\n                      trailing: const Icon(Icons.chevron_right),\n                      onTap: () => controller.selectEvidence(item.id),\n                    ),\n                ],\n              ),\n            ),\n          ),\n          if (selected != null) ...<Widget>[\n            const SizedBox(height: 12),\n            _evidenceViewer(context, selected),\n          ],\n        ],\n        const _BoundaryNotice(\n          message:\n              'Evidence shown here is deterministic saved-run fixture data. It does not claim a live evidence-store read, independent certification, or production support.',\n        ),\n      ],\n    );\n  }\n\n  Widget _evidenceViewer(BuildContext context, P5EvidenceFixture fixture) {\n    return Card(\n      key: Key('evidence-viewer-${fixture.kind.name}'),\n      child: Padding(\n        padding: const EdgeInsets.all(18),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: <Widget>[\n            Row(\n              children: <Widget>[\n                Icon(_evidenceKindIcon(fixture.kind)),\n                const SizedBox(width: 8),\n                Expanded(\n                  child: Text(\n                    fixture.title,\n                    style: Theme.of(context).textTheme.titleLarge,\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 6),\n            Text('${fixture.mediaType} • ${fixture.byteLength} bytes'),\n            const SizedBox(height: 12),\n            _evidenceViewerBody(context, fixture),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _evidenceViewerBody(\n    BuildContext context,\n    P5EvidenceFixture fixture,\n  ) {\n    switch (fixture.kind) {\n      case P5EvidenceKind.image:\n        return Container(\n          key: const Key('evidence-image-preview'),\n          height: 180,\n          alignment: Alignment.center,\n          decoration: BoxDecoration(\n            border: Border.all(color: Theme.of(context).dividerColor),\n            borderRadius: BorderRadius.circular(12),\n          ),\n          child: Column(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: <Widget>[\n              const Icon(Icons.image_outlined, size: 64),\n              const SizedBox(height: 8),\n              const Text('640 × 360 deterministic image preview'),\n              Text(fixture.content.split('\\n').last),\n            ],\n          ),\n        );\n      case P5EvidenceKind.markdown:\n        return Column(\n          key: const Key('evidence-markdown-preview'),\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: fixture.content.split('\\n').map((line) {\n            if (line.startsWith('# ')) {\n              return Padding(\n                padding: const EdgeInsets.only(bottom: 8),\n                child: Text(\n                  line.substring(2),\n                  style: Theme.of(context).textTheme.titleMedium,\n                ),\n              );\n            }\n            return SelectableText(line);\n          }).toList(growable: false),\n        );\n      case P5EvidenceKind.table:\n        final rows = fixture.content\n            .split('\\n')\n            .map((line) => line.split('|'))\n            .toList(growable: false);\n        final header = rows.first;\n        return SingleChildScrollView(\n          key: const Key('evidence-table-preview'),\n          scrollDirection: Axis.horizontal,\n          child: DataTable(\n            columns: header\n                .map((cell) => DataColumn(label: Text(cell)))\n                .toList(growable: false),\n            rows: rows\n                .skip(1)\n                .map(\n                  (row) => DataRow(\n                    cells: row\n                        .map((cell) => DataCell(Text(cell)))\n                        .toList(growable: false),\n                  ),\n                )\n                .toList(growable: false),\n          ),\n        );\n      case P5EvidenceKind.citation:\n        return Container(\n          key: const Key('evidence-citation-preview'),\n          padding: const EdgeInsets.all(12),\n          decoration: BoxDecoration(\n            border: Border.all(color: Theme.of(context).dividerColor),\n            borderRadius: BorderRadius.circular(12),\n          ),\n          child: SelectableText(fixture.content),\n        );\n      case P5EvidenceKind.textMetadata:\n      case P5EvidenceKind.binaryMetadata:\n      case P5EvidenceKind.json:\n      case P5EvidenceKind.diff:\n      case P5EvidenceKind.receipt:\n        return SelectableText(\n          fixture.content,\n          key: Key('evidence-${fixture.kind.name}-preview'),\n          style: const TextStyle(fontFamily: 'monospace'),\n        );\n    }\n  }\n\n  IconData _evidenceKindIcon(P5EvidenceKind kind) {\n    return switch (kind) {\n      P5EvidenceKind.textMetadata => Icons.text_snippet_outlined,\n      P5EvidenceKind.binaryMetadata => Icons.data_object_outlined,\n      P5EvidenceKind.image => Icons.image_outlined,\n      P5EvidenceKind.markdown => Icons.article_outlined,\n      P5EvidenceKind.json => Icons.code_outlined,\n      P5EvidenceKind.table => Icons.table_chart_outlined,\n      P5EvidenceKind.diff => Icons.difference_outlined,\n      P5EvidenceKind.citation => Icons.format_quote_outlined,\n      P5EvidenceKind.receipt => Icons.receipt_long_outlined,\n    };\n  }\n\n  Widget _ownerModeWorkspace(BuildContext context) {\n""",
)

test_path = 'test/product/p5_information_architecture/p5_evidence_viewers_test.dart'
Path(test_path).write_text(
    """import 'package:flutter/material.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:kristin_local_agent/product/p5_information_architecture/p5_controller.dart';\nimport 'package:kristin_local_agent/product/p5_information_architecture/p5_fixtures.dart';\nimport 'package:kristin_local_agent/product/p5_information_architecture/p5_models.dart';\nimport 'package:kristin_local_agent/product/p5_information_architecture/p5_prototype.dart';\n\nvoid main() {\n  TestWidgetsFlutterBinding.ensureInitialized();\n\n  test('P5-009 exposes all nine evidence kinds for every saved run', () {\n    expect(P5EvidenceKind.values, hasLength(9));\n    for (final run in P5PrototypeFixtures.runs) {\n      final evidence = P5PrototypeFixtures.evidenceForRun(run.id);\n      expect(evidence, hasLength(P5EvidenceKind.values.length));\n      expect(evidence.map((item) => item.kind).toSet(), P5EvidenceKind.values.toSet());\n      expect(evidence.every((item) => item.runId == run.id), isTrue);\n      expect(evidence.every((item) => item.byteLength > 0), isTrue);\n    }\n    expect(P5PrototypeFixtures.evidenceForRun('run.unknown'), isEmpty);\n  });\n\n  test('P5-009 evidence selection fails closed outside the saved run', () {\n    final controller = P5InformationArchitectureController();\n    controller.selectEvidence('evidence.run.unknown.json');\n    expect(controller.state.selectedEvidenceId, isNull);\n    expect(\n      controller.state.recoveryMessage,\n      'Typed evidence can only reopen from a deterministic saved run.',\n    );\n\n    controller.selectRun('run.p5-complete-001');\n    controller.selectEvidence('evidence.run.other.json');\n    expect(controller.state.selectedEvidenceId, isNull);\n    expect(controller.state.recoveryMessage, contains('is not part of saved run'));\n  });\n\n  testWidgets('P5-009 reopens every viewer from a saved run and retains selection',\n      (tester) async {\n    tester.view.physicalSize = const Size(1440, 1100);\n    tester.view.devicePixelRatio = 1;\n    addTearDown(tester.view.resetPhysicalSize);\n    addTearDown(tester.view.resetDevicePixelRatio);\n\n    final controller = P5InformationArchitectureController();\n    controller.changeExperienceLevel(P5ExperienceLevel.advanced);\n    controller.selectRun('run.p5-complete-001');\n    controller.selectWorkspace(P5WorkspaceId.evidence);\n\n    await tester.pumpWidget(\n      MaterialApp(\n        home: Scaffold(\n          body: P5InformationArchitecturePrototype(controller: controller),\n        ),\n      ),\n    );\n    await tester.pump();\n\n    expect(find.byKey(const Key('saved-run-evidence-index')), findsOneWidget);\n    for (final kind in P5EvidenceKind.values) {\n      final item = find.byKey(Key('evidence-item-${kind.name}'));\n      expect(item, findsOneWidget);\n      await tester.ensureVisible(item);\n      await tester.tap(item);\n      await tester.pump();\n      final viewer = find.byKey(Key('evidence-viewer-${kind.name}'));\n      expect(viewer, findsOneWidget);\n      expect(controller.state.selectedEvidenceId, contains(kind.name));\n    }\n\n    final selectedId = controller.state.selectedEvidenceId;\n    expect(selectedId, contains(P5EvidenceKind.receipt.name));\n    controller.selectWorkspace(P5WorkspaceId.projects);\n    await tester.pump();\n    controller.selectWorkspace(P5WorkspaceId.evidence);\n    await tester.pump();\n    expect(controller.state.selectedEvidenceId, selectedId);\n    expect(\n      find.byKey(Key('evidence-viewer-${P5EvidenceKind.receipt.name}')),\n      findsOneWidget,\n    );\n  });\n\n  testWidgets('P5-009 current in-memory run does not fabricate saved evidence',\n      (tester) async {\n    tester.view.physicalSize = const Size(1280, 900);\n    tester.view.devicePixelRatio = 1;\n    addTearDown(tester.view.resetPhysicalSize);\n    addTearDown(tester.view.resetDevicePixelRatio);\n\n    final initial = P5PrototypeFixtures.initialState().copyWith(\n      experienceLevel: P5ExperienceLevel.advanced,\n      workspace: P5WorkspaceId.evidence,\n      reopenWorkspace: P5WorkspaceId.evidence,\n      selectedRunId: 'run.p5-simulated-current',\n      runState: P5RunPresentationState.running,\n    );\n    final controller = P5InformationArchitectureController(initialState: initial);\n\n    await tester.pumpWidget(\n      MaterialApp(\n        home: Scaffold(\n          body: P5InformationArchitecturePrototype(controller: controller),\n        ),\n      ),\n    );\n    await tester.pump();\n\n    expect(find.byKey(const Key('evidence-no-saved-run')), findsOneWidget);\n    expect(find.byKey(const Key('saved-run-evidence-index')), findsNothing);\n  });\n}\n""",
    encoding='utf-8',
    newline='\n',
)
